<template>
  <main class="production-workspace">
    <header class="page-heading"><div><h1>机台生产</h1><p>选择机台订单，登记已保存数量，核对后完成本机台工艺。</p></div><el-button v-if="active" :disabled="busy" @click="refresh">重新读取</el-button></header>
    <section class="machine-entry" aria-label="机台定位"><label for="machine-production-scan">机台扫码</label><el-input id="machine-production-scan" v-model="machineText" :disabled="busy" placeholder="扫描机台标签" @keyup.enter="scanMachine(false)" /><el-button :loading="busy" @click="scanMachine(false)">识别机台</el-button><el-button v-if="active" :disabled="busy" @click="scanMachine(true)">重新选单</el-button></section>
    <p v-if="error" class="error" role="alert">{{ error }}</p>
    <nav v-if="Object.keys(sessions).length" class="machine-tabs" aria-label="已选机台"><el-button v-for="session in sessions" :key="session.selection.context.machine_id" :disabled="busy" :type="session.selection.context.machine_id === active?.context.machine_id ? 'primary' : 'default'" @click="switchMachine(session)">{{ session.selection.state.machine_no }} · {{ session.selection.state.plan_no }}</el-button></nav>
    <section v-if="machineResult?.scan_ticket" class="selection-panel" aria-label="机台订单选择"><h2>{{ machineResult.machine.name }} · {{ machineResult.machine.machine_no }}</h2><p>请选择实际订单、产品与工艺。选择本身不会开始生产。</p><el-select v-model="selectedStateId" :disabled="busy" placeholder="选择本机台已配置订单工艺" aria-label="机台订单工艺"><el-option v-for="state in machineResult.assignments" :key="state.id" :value="state.id" :label="`${state.plan_no} · ${state.part_name || state.customer_part_no || state.product_code} · ${state.process_code} · ${status(state.production_status)} · 路线版本 v${state.route_revision}`" /></el-select><el-button :disabled="busy || !selectedStateId" @click="selectOrder">进入订单</el-button><p v-if="!machineResult.assignments.length" class="note">该机台没有当前账号可用的订单工艺，请先完成订单配置与机台分配。</p></section>
    <section v-if="active" class="production-panel" aria-label="当前机台生产">
      <header class="state-heading"><div><h2>{{ active.state.plan_no }} · {{ active.state.part_name || '未维护产品名称' }}</h2><p>{{ active.state.machine_name }}（{{ active.state.machine_no }}） · {{ active.state.product_code }} · {{ active.state.customer_part_no || '未维护客户件号' }} · {{ active.state.process_code }}</p></div><el-tag effect="plain">{{ status(active.state.production_status) }}</el-tag></header>
      <div class="quantities"><div><span>已保存数量</span><strong>{{ active.state.current_qty.toLocaleString() }} <small>件</small></strong></div><div><span>本机台工艺目标</span><b>{{ active.state.target_qty.toLocaleString() }} 件</b></div><div><span>数量差异</span><b>{{ active.state.difference_qty > 0 ? '+' : '' }}{{ active.state.difference_qty.toLocaleString() }} 件</b></div></div>
      <p v-if="active.state.blocked" class="error">当前机台工艺已暂停，请由负责人处理异常后继续。</p>
      <p v-else-if="active.state.production_status === 'completed'" class="note">本机台工艺已完成。产品框可继续后续工艺；本工艺数量由生产主管按原因更正。</p>
      <section v-if="active.state.allowed_actions.includes('quantity')" class="quantity-entry" aria-label="产品框数量登记"><h3>当前产品框</h3><div class="scan-row"><el-input v-model="frameText" :disabled="busy" aria-label="产品框扫码内容" placeholder="扫描产品框标签，定位实物" @keyup.enter="scanFrame" /><el-button :disabled="busy || !frameText.trim()" @click="scanFrame">定位产品框</el-button></div>
        <template v-if="frame">
          <template v-if="frame.box">
            <div v-if="needsHandoff" class="frame-form"><p>当前框：{{frame.box.product_name_snapshot}} · {{frame.box.current_process_code}} · {{frame.box.current_qty}} 件。目标选单：{{active.state.process_code}}。<span v-if="frame.box.current_qty<=0">该框已无余量，不能进入工艺。</span></p><el-button type="primary" :disabled="busy || frame.box.current_qty<=0" @click="handoffVisible=true">进入所选工艺</el-button></div>
            <p v-else-if="selectedFrameQuantity?.quantity_locked" class="note">该框已拆分，本工艺保留拆分余额；请继续后续工艺或查看追溯。</p>
            <template v-else>
              <div v-if="!selectedFrameQuantity" class="scan-row material-source"><el-input v-model="materialText" :disabled="busy" aria-label="本框原材料扫码" placeholder="首次登记可扫描实际原材料或子卷标签" @input="sourceMaterial=null" @keyup.enter="scanMaterial"/><el-button :disabled="busy || !materialText.trim()" @click="scanMaterial">核对材料来源</el-button><span v-if="sourceMaterial">{{sourceMaterial.material_name || '历史物料'}} · {{sourceMaterial.batch_no}}</span></div>
              <p v-else class="note">{{selectedFrameQuantity.material_batch_id ? '已保留材料来源，可在追溯详情核对。' : '此工艺未记录材料来源，历史记录保持原样。'}}</p>
              <div class="frame-form"><div><strong>{{ frame.box.product_name_snapshot || '当前产品' }}</strong><p>{{ frame.box.customer_part_no || '未维护客户件号' }} · 已保存 {{ frame.box.current_qty }} 件</p></div><el-input-number :key="busy ? 'working' : 'ready'" v-model="frameQuantity" :disabled="busy" :min="0" :max="2147483647" :step="1" step-strictly aria-label="本框当前数量" /><el-button type="primary" :disabled="busy || !isQuantity(frameQuantity)" @click="saveQuantity">保存当前数量</el-button></div>
            </template>
            <el-button link :disabled="busy" @click="openTrace(frame.box.id)">查看当前框追溯</el-button>
          </template>
          <div v-else><p class="note">此标签尚未绑定，可一次绑定到上方订单产品。</p><el-button :disabled="busy || !active.state.allowed_actions.includes('bind')" @click="bindFrame">绑定到当前订单</el-button></div>
          <details class="trace-details"><summary>当前标签标识</summary><code>{{ frame.pool_item.public_code }}</code></details>
        </template>
        <p class="note">每次保存覆盖本框当前值，多次扫码不会累加数量。用途按首次产出显示，后续工艺数量不重复分配。</p>
      </section>
      <el-table :data="active.state.boxes" row-key="quantity_id" empty-text="该机台工艺尚无已保存产品框" class="box-table">
        <el-table-column label="产品 / 件号" min-width="200"><template #default="{row}"><strong>{{ row.product_name }}</strong><span class="subline">{{ row.customer_part_no || '未维护客户件号' }}</span></template></el-table-column>
        <el-table-column label="已保存数量" width="125" align="right"><template #default="{row}"><b>{{ row.current_qty }} 件</b></template></el-table-column>
        <el-table-column label="来源订单用途" width="125" align="right"><template #default="{row}">{{ row.allocation ? row.allocation.order_qty + ' 件' : '尚无产出来源' }}</template></el-table-column>
        <el-table-column label="来源备货用途" width="125" align="right"><template #default="{row}">{{ row.allocation ? row.allocation.stock_qty + ' 件' : '—' }}</template></el-table-column>
        <el-table-column label="框号（辅助）" min-width="210"><template #default="{row}"><code>{{ row.box_no }}</code></template></el-table-column>
        <el-table-column label="操作" width="260"><template #default="{row}"><el-button link :disabled="busy" @click="openTrace(row.box_id)">查看追溯</el-button><el-button v-if="row.can_correct" link :disabled="busy" @click="openCorrection(row)">更正数量</el-button><el-button v-if="row.allocation?.allowed_actions.includes('allocate')" link :disabled="busy" @click="openAllocation(row.allocation)">分配用途</el-button></template></el-table-column>
      </el-table>
      <footer v-if="active.state.allowed_actions.includes('complete')" class="completion"><p class="note">再次扫描当前机台，核对已保存数量后确认完成。多台机的选单互不覆盖。</p><el-button type="primary" :disabled="busy || !completionReady" @click="openCompletion">确认本机台完成</el-button></footer>
    </section>
    <p v-else-if="!machineResult" class="empty-state">先扫描机台，再从本机台的有效订单工艺中明确选单。</p>
    <el-dialog v-model="handoffVisible" title="确认进入后续工艺" width="480px" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy"><p v-if="frame?.box && active">{{active.state.plan_no}} · {{frame.box.product_name_snapshot}} · {{frame.box.current_process_code}} → {{active.state.process_code}}</p><p v-if="frame?.box" class="confirm-quantity">本次入量 {{frame.box.current_qty}} 件，沿用当前产品框。</p><p v-if="error" class="error" role="alert">{{error}}</p><template #footer><el-button :disabled="busy" @click="handoffVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="handoff">确认进入工艺</el-button></template></el-dialog>
    <el-dialog v-model="traceVisible" title="产品框工艺与来源追溯" width="1120px" destroy-on-close><TraceDetail v-if="traceId && traceVisible" :box-id="traceId" @navigate="traceId=$event"/></el-dialog>
    <el-dialog v-model="completionVisible" title="确认本机台工艺完成" width="480px" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy"><template v-if="active"><p>{{ active.state.plan_no }} · {{ active.state.process_code }} · {{ active.state.machine_no }}</p><p class="confirm-quantity">已保存 {{ active.state.current_qty }} 件 / 目标 {{ active.state.target_qty }} 件</p><el-checkbox v-if="active.state.difference_qty !== 0" v-model="differenceConfirmed" :disabled="busy">已核对数量差异 {{ active.state.difference_qty }} 件，确认完成</el-checkbox></template><p v-if="error" class="error" role="alert">{{ error }}</p><template #footer><el-button :disabled="busy" @click="completionVisible=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!active || (active.state.difference_qty !== 0 && !differenceConfirmed)" @click="complete">确认完成</el-button></template></el-dialog>
    <el-dialog v-model="correctionVisible" title="更正已完成工艺数量" width="480px" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy"><p class="note">填写实物复核数量和原因；已存在的下游数量及用途事实保持原记录。</p><el-form label-position="top"><el-form-item label="更正后数量"><el-input-number :key="busy ? 'working' : 'ready'" v-model="correctionQty" :min="0" :max="2147483647" step-strictly :disabled="busy" aria-label="更正后数量" /></el-form-item><el-form-item label="更正原因"><el-input v-model="correctionReason" type="textarea" :disabled="busy" maxlength="500" aria-label="更正原因" /></el-form-item></el-form><p v-if="error" class="error" role="alert">{{ error }}</p><template #footer><el-button :disabled="busy" @click="correctionVisible=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!isQuantity(correctionQty) || !correctionReason.trim()" @click="correct">保存更正</el-button></template></el-dialog>
    <el-dialog v-model="allocationVisible" title="分配订单与备货用途" width="480px" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy"><template v-if="allocationTarget"><p>有效产出 {{ allocationTarget.available_qty }} 件</p><el-form label-position="top"><el-form-item label="订单用途数量"><el-input-number :key="busy ? 'working' : 'ready'" v-model="allocationOrder" :min="0" :max="allocationTarget.available_qty" step-strictly :disabled="busy" aria-label="订单用途数量" /></el-form-item><el-form-item label="备货用途数量"><strong>{{ allocationTarget.available_qty - (allocationOrder || 0) }} 件</strong></el-form-item></el-form></template><p v-if="error" class="error" role="alert">{{ error }}</p><template #footer><el-button :disabled="busy" @click="allocationVisible=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!isQuantity(allocationOrder)" @click="allocate">保存用途分配</el-button></template></el-dialog>
  </main>
</template>

<script setup lang="ts">
import {computed, ref} from 'vue'
import {ElMessage} from 'element-plus'
import {productProductionApi as api} from '@/api/productProduction'
import {productBoxesApi as boxesApi} from '@/api/productBoxes'
import {productTraceApi} from '@/api/productTrace'
import {materialQrApi} from '@/api/materialQr'
import TraceDetail from '@/components/product-box-qr/TraceDetail.vue'
import type {MaterialBatchScanResponse} from '@/types/legacyQr'
import type {ProductBoxScan, QrId} from '@/types/productBox'
import type {MachineScan, OutputAllocation, ProductionBox, ProductionSelection} from '@/types/productProduction'
import {qrError} from './messages'
type Session = {selection: ProductionSelection; machineQr: string}
const busy=ref(false), error=ref(''), machineText=ref(''), machineResult=ref<MachineScan|null>(null), selectedStateId=ref<QrId>()
const sessions=ref<Record<number,Session>>({}), active=ref<ProductionSelection|null>(null), currentMachineQr=ref(''), completionReady=ref(false)
const frameText=ref(''), frame=ref<ProductBoxScan|null>(null), frameQuantity=ref<number>(), completionVisible=ref(false), differenceConfirmed=ref(false)
const correctionVisible=ref(false), correctionTarget=ref<ProductionBox|null>(null), correctionQty=ref<number>(), correctionReason=ref('')
const allocationVisible=ref(false), allocationTarget=ref<OutputAllocation|null>(null), allocationOrder=ref<number>()
const materialText=ref(''), sourceMaterial=ref<MaterialBatchScanResponse|null>(null), handoffVisible=ref(false), traceVisible=ref(false), traceId=ref<QrId>()
const selectedFrameQuantity=computed(()=>active.value?.state.boxes.find(row=>row.box_id===frame.value?.box?.id))
const needsHandoff=computed(()=>!!frame.value?.box?.current_process_code && frame.value.box.current_process_code!==active.value?.state.process_code)
function openTrace(id:QrId){traceId.value=id;traceVisible.value=true}
async function scanMaterial(){await work(async()=>{sourceMaterial.value=null;const raw=materialText.value.trim(),match=/^MAT:([1-9]\d*):\d{8}(?:\d{6})?(?::.*)?$/.exec(raw);const id=Number(match?.[1]);if(!Number.isSafeInteger(id)||id<=0||id>2147483647)throw new Error('请扫描有效的原材料或子卷标签。');const result=await materialQrApi.scanQr(id);if(result.qr_code!==raw)throw new Error('扫码内容与已保存材料身份不一致。');sourceMaterial.value=result})}
async function handoff(){const selected=active.value,box=frame.value?.box;if(!selected||!box)return;await work(async()=>{const result=await productTraceApi.advance(box.id,{context_id:selected.context.id,expected_version:box.version,state_version:selected.state.version,idempotency_key:key()});accept({context:result.context!,state:result.state});if(frame.value)frame.value.box=result.box;frameQuantity.value=result.box.current_qty;sourceMaterial.value=null;materialText.value='';completionReady.value=false;handoffVisible.value=false;ElMessage.success('已进入所选工艺，来源与入量已保留')})}
function status(value:string){return ({pending:'待生产',in_progress:'生产中',completed:'已完成'} as Record<string,string>)[value]||value}
function isQuantity(value:unknown):value is number{return typeof value==='number'&&Number.isInteger(value)&&value>=0&&value<=2147483647}
const key=()=>crypto.randomUUID()
async function work(operation:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await operation()}catch(reason){error.value=qrError(reason)}finally{busy.value=false}}
function accept(selection:ProductionSelection){active.value=selection;sessions.value[selection.context.machine_id]={selection,machineQr:currentMachineQr.value}}
function clearFrame(){frame.value=null;frameText.value='';frameQuantity.value=undefined;sourceMaterial.value=null;materialText.value='';handoffVisible.value=false}
function switchMachine(session:Session){if(busy.value)return;active.value=session.selection;currentMachineQr.value=session.machineQr;machineText.value=session.machineQr;machineResult.value=null;completionReady.value=false;clearFrame();error.value=''}
async function scanMachine(fresh:boolean){if(!machineText.value.trim())return;await work(async()=>{const raw=machineText.value.trim(), id=Number(/^MCN:([1-9]\d*):/.exec(raw)?.[1]);const cached=sessions.value[id]?.selection;const result=await api.scanMachine({machine_qr:raw,...(!fresh&&cached?.state.allowed_actions.includes('complete')?{context_id:cached.context.id}:{})});currentMachineQr.value=raw;machineResult.value=result;selectedStateId.value=undefined;completionReady.value=result.completion_intent;clearFrame();if(result.context&&result.state){accept({context:result.context,state:result.state});machineResult.value=null}else active.value=null})}
async function selectOrder(){const result=machineResult.value, state=result?.assignments.find(item=>item.id===selectedStateId.value);if(!result?.scan_ticket||!state)return;await work(async()=>{const selection=await api.select({scan_ticket:result.scan_ticket!,assignment_id:state.assignment_id,order_product_id:state.order_product_id,process_code:state.process_code,state_id:state.id,idempotency_key:key()});accept(selection);machineResult.value=null;completionReady.value=false;clearFrame()})}
async function readState(){if(!active.value)return;const original=active.value;const result=await api.scanMachine({machine_qr:currentMachineQr.value});const state=result.assignments.find(state=>state.id===original.state.id);if(!state)throw new Error('当前工艺已不可用，请重新扫描机台并选单。');accept({context:original.context,state});completionReady.value=false;if(frame.value){const refreshed=await boxesApi.scan(frame.value.pool_item.qr_payload);frame.value=refreshed;frameQuantity.value=refreshed.box?.current_qty}}
async function refresh(){await work(readState)}
async function scanFrame(){if(!active.value||!frameText.value.trim())return;await work(async()=>{frame.value=null;sourceMaterial.value=null;materialText.value='';const result=await boxesApi.scan(frameText.value.trim());if(result.box&&(result.box.order_product_id!==active.value!.state.order_product_id||result.box.route_revision_id!==active.value!.state.route_revision_id))throw new Error('该框与当前订单产品或路线版本不一致，请核对实物和选单。');frame.value=result;frameQuantity.value=result.box?.current_qty})}
async function bindFrame(){if(!active.value||!frame.value||frame.value.box||!active.value.state.allowed_actions.includes('bind'))return;await work(async()=>{frame.value=await boxesApi.bind({qr_payload:frame.value!.pool_item.qr_payload,order_product_id:active.value!.state.order_product_id,context_id:active.value!.context.id,idempotency_key:key()});frameQuantity.value=frame.value.box?.current_qty})}
async function saveQuantity(){const selected=active.value, box=frame.value?.box, amount=frameQuantity.value;if(!selected||!box||!isQuantity(amount)||needsHandoff.value)return;if(materialText.value.trim()&&!sourceMaterial.value){error.value='请先核对输入的材料来源，或清空材料输入后保存。';return}await work(async()=>{const result=await api.saveQuantity(box.id,{context_id:selected.context.id,current_qty:amount,expected_version:box.version,state_version:selected.state.version,idempotency_key:key(),...(sourceMaterial.value?{material_batch_id:sourceMaterial.value.id}:{})});accept({context:result.context!,state:result.state});if(frame.value)frame.value.box=result.box;frameQuantity.value=result.box.current_qty;sourceMaterial.value=null;materialText.value='';completionReady.value=false;ElMessage.success('当前数量已保存')})}
function openCompletion(){if(!completionReady.value||busy.value)return;error.value='';differenceConfirmed.value=false;completionVisible.value=true}
async function complete(){const selected=active.value;if(!selected||!completionReady.value)return;await work(async()=>{const result=await api.complete(selected.context.machine_id,{context_id:selected.context.id,confirm_quantity_difference:differenceConfirmed.value,expected_version:selected.state.version,idempotency_key:key()});accept(result);completionReady.value=false;completionVisible.value=false;clearFrame();ElMessage.success('本机台工艺已完成')})}
function openCorrection(row:ProductionBox){correctionTarget.value=row;correctionQty.value=row.current_qty;correctionReason.value='';error.value='';correctionVisible.value=true}
async function correct(){const selected=active.value,row=correctionTarget.value,amount=correctionQty.value;if(!selected||!row||!isQuantity(amount)||!correctionReason.value.trim())return;await work(async()=>{const result=await api.correct(row.box_id,{state_id:selected.state.id,current_qty:amount,reason:correctionReason.value.trim(),expected_version:row.box_version,state_version:selected.state.version,idempotency_key:key()});accept({context:selected.context,state:result.state});correctionVisible.value=false;ElMessage.success('更正已保存并保留历史')})}
function openAllocation(value:OutputAllocation){allocationTarget.value=value;allocationOrder.value=value.order_qty;error.value='';allocationVisible.value=true}
async function allocate(){const target=allocationTarget.value, amount=allocationOrder.value;if(!target||!isQuantity(amount))return;await work(async()=>{await api.allocate({source_quantity_id:target.source_quantity_id,order_qty:amount,stock_qty:target.available_qty-amount,expected_version:target.version,idempotency_key:key()});await readState();allocationVisible.value=false;ElMessage.success('用途分配已保存')})}
</script>

